export function getBilingualAssessment(uiLang, learningLang, educationLevel) {
  const key = `${uiLang}-${learningLang}`;
  if (BILINGUAL_ASSESSMENTS[key] && BILINGUAL_ASSESSMENTS[key][educationLevel]) {
    return BILINGUAL_ASSESSMENTS[key][educationLevel];
  }
  return null;
}
